    {
      "id": "tracking.before-authorization",
      "title": "Tracking starts before the person answers the tracking prompt",
      "severity": "warning",
      "evidence": [
        "source",
        "runtime",
        "human"
      ],
      "enforced_by": "app-review",
      "automation": "assisted",
      "guidelines": [
        "5.1.2"
      ],
      "applies_when": [
        "advertising"
      ],
      "summary": "An ad or attribution SDK starts, or code reads the advertising identifier, at launch, while the App Tracking Transparency request comes later or only on some paths. Data sent before the answer is tracking without permission, which guideline 5.1.2(i) forbids. If the app tracks from launch, the system prompt must come before any tracking data is collected.",
      "fix": "Start tracking SDKs, or enable their tracking features, only in the completion of `requestTrackingAuthorization` and only when the status is `.authorized`. Read `advertisingIdentifier` only after authorization; before it, the identifier is all zeros anyway.",
      "references": [
        "https://developer.apple.com/documentation/apptrackingtransparency",
        "https://developer.apple.com/design/human-interface-guidelines/privacy"
      ],
      "check": {
        "id": "tracking-init-order",
        "confidence": "low",
        "catalog": "tracking-sdks",
        "kinds": [
          "advertising",
          "attribution"
        ],
        "early_contexts": [
          "didFinishLaunchingWithOptions",
          "willFinishLaunchingWithOptions",
          "App.init",
          "@main"
        ],
        "gate_signals": [
          "trackingAuthorizationStatus",
          "requestTrackingAuthorization",
          ".authorized"
        ]
      },
      "review": [
        "With tracking denied, does any SDK still send the advertising identifier or cross-app identifiers?"
      ]
    },
    {
      "id": "tracking.fingerprinting",
      "title": "Device signals collected in a way that looks like fingerprinting",
      "severity": "warning",
      "evidence": [
        "source",
        "human"
      ],
      "enforced_by": "app-review",
      "automation": "manual",
      "guidelines": [
        "5.1.2"
      ],
      "applies_when": [],
      "summary": "Fingerprinting is not allowed, with or without tracking permission: the Developer Program License Agreement forbids deriving data from a device to identify it uniquely, and apps whose SDKs do it may be rejected. Combining signals such as boot time, disk size, keyboard list, screen metrics, or locale into an identifier, or sending required reason API data off-device, breaks both that rule and the declared reasons. Guideline 5.1.2(iii) also bans building user profiles surreptitiously or re-identifying people from data described as anonymous or aggregated.",
      "fix": "Use required reason APIs only for their declared reasons, keep derived values on-device unless the reason allows otherwise, and never combine device signals into an identifier. Use `identifierForVendor` or an account ID for first-party needs.",
      "references": [
        "https://developer.apple.com/app-store/user-privacy-and-data-use/"
      ],
      "review": [
        "Does any code or SDK combine device properties into an identifier or send them to a server?",
        "Does the app or a partner join data described as anonymous or aggregated back to individual people?"
      ]
    },
    {
      "id": "tracking.prompt-not-shown",
      "title": "Tracking purpose string declared but the prompt never appears",
      "severity": "error",
      "evidence": [
        "plist",
        "source",
        "runtime"
      ],
      "enforced_by": "app-review",
      "automation": "assisted",
      "guidelines": [
        "5.1.2",
        "2.1"
      ],
      "applies_when": [],
      "summary": "`NSUserTrackingUsageDescription` is set, or the App Privacy details say the app tracks, but the reviewer never sees the App Tracking Transparency prompt. Common causes: the app never calls `requestTrackingAuthorization`, or calls it at launch before the app is active, when the system skips the prompt. Reviewers then reject the build because they cannot find the request.",
      "fix": "Call `ATTrackingManager.requestTrackingAuthorization` once the app is active, for example from the first screen's task or after `sceneDidBecomeActive`, not in `application(_:didFinishLaunchingWithOptions:)`. If the app does not track, remove the purpose string and set tracking to No in App Privacy. Say in the review notes where the prompt appears.",
      "references": [
        "https://developer.apple.com/documentation/apptrackingtransparency/attrackingmanager/requesttrackingauthorization(completionhandler:)"
      ],
      "check": {
        "id": "att-prompt-reachable",
        "confidence": "medium",
        "plist_keys": [
